const e={type:"config",goal:"02",title:"Reversing Gains: A World With Rising Hunger",shortTitle:"Global Hunger",abstract:"After decades of progress, global hunger has been rising again since 2015, hitting Sub Saharan Africa and the Middle East the hardest. Escalating conflicts, frequent climate shocks, and fragile food supply chains have fueled this reversal. Are countries still on track to end hunger, and which ones are beating the odds?",citation:'Wadhwa, D. and Lambrechts, M. 2026. “<a href="https://doi.org/10.60616/w2jr-xz63" target="_blank" rel="external">Reversing Gains: A World With Rising Hunger</a>.” In Atlas of Global Development 2026, edited by A F Pirlea, D Wadhwa, D Mahler, U Serajuddin, A Thudt, and M Welch. Washington DC: World Bank. License: Creative Commons Attribution CC BY 3.0 IGO.',credits:"Divyanshi Wadhwa",inputs:"Bo Pieter Johannes Andree, Bryce Charron, Lorena Corso, Moritz Meyer, Sharad Alan Tandon, Sawaid Abbas, Faisal Mueen Qamer",visuals:"Maarten Lambrechts",homeFactoidNumber:"In 51 of 97",homeFactoidPercent:"53",homeFactoidText:"economies hunger has worsened or made no progress since 2015.",homeTagline:"After decades of progress, global hunger has been rising again. What is driving the reversal, and can countries get back on track to end hunger?",theme:"people",publicationDate:"2026-12-01",slug:"world-with-rising-hunger",keyFacts:[{_key:"k2231",contentBlockKey:"c7",keyFact:"115 million ",keyFactLabel:"more people faced hunger in 2024, compared to 2015."},{_key:"k2545",contentBlockKey:"ab8be123ef41",keyFact:"In 51 economies",keyFactLabel:"hunger has worsened or made no progress since 2015."},{_key:"k2365",contentBlockKey:"c23",keyFact:"1 in 5",keyFactLabel:"people in fragile and conflict-affected economies face hunger."}]},a=[{_key:"k2200",type:"subhed",text:"Global rise in hunger"},{_key:"k2201-k2206",type:"text",text:`Access to enough food is a basic human necessity.<div class="summary reference"><div class="bg" aria-label="reference 1"><label for='reference_1_1_318581690' aria-hidden="true">1</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_1_1_318581690'/><div class="details">FAO. <a href="https://www.fao.org/right-to-food/en" target="_blank" rel="external">Right to Food</a>. Food and Agriculture Organization of the United Nations.</div></div> Yet this necessity remains unmet for over 650 million people globally.`},{_key:"k2201-48b97c27b2a1",type:"text",text:`So how do we measure hunger? One widely used measure is <strong>prevalence of undernourishment: </strong>the share of people whose usual food intake does not provide enough energy to maintain a normal, active, healthy life.<div class="summary reference"><div class="bg" aria-label="reference 2"><label for='reference_2_1_1454908558' aria-hidden="true">2</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_2_1_1454908558'/><div class="details">FAO. “I<a href="http://www.fao.org/sustainable-development-goals-data-portal/data/indicators/2.1.1-prevalence-of-undernourishment/en" target="_blank" rel="external">ndicator 2.1.1 - Prevalence of undernourishment.</a>” SDG Indicators Data Portal. Food and Agriculture Organization of the United Nations. </div></div>`},{_key:"k2201-7cae8ea966c9",type:"text",text:"And while the world made steady progress against hunger for decades, that progress has stalled and, in many places, reversed. Over the past decade, global hunger has risen at an alarming rate."},{_key:"k2217",type:"factoid",title:"In 2024",number:"650 ",units:"million people",label:"were undernourished."},{_key:"c7",type:"scroller",graphic:"prevalence_undernourishment_regions",title:"Global hunger is on the rise",subtitle:"",source:`FAO and WDI (2026).<div class="summary reference"><div class="bg" aria-label="reference 3"><label for='reference_3_1_681842539' aria-hidden="true">3</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_3_1_681842539'/><div class="details">FAO. <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>).</div></div>`,visSize:"default",visdescription:"The chart shows changes in the prevalence of undernourishment, measured as a percentage of the population, from 2001 to 2024 for the world and the seven World Bank Group regions. Values for 2014 and 2024 are highlighted. Globally, the prevalence of undernourishment increased from 7.4% in 2014 to 8.1% in 2024. Sub-Saharan Africa had the highest rate in 2024, rising from 17.9% to 22.3%, while the Middle East, North Africa, Afghanistan and Pakistan increased from 9.8% to 12.3%. ",data:"prevalence_undernourishment_regions",anchorKey:"c7",disableDataDownload:!1,disableScreenshot:!1,Source:'Retrieved from World Development Indicators (<a href="http://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>). <a href="http://fao.org/faostat/en/#home " target="_blank" rel="external">Food and Agriculture Organization of the United Nations (FAO) </a>',y_axis_title:"Prevalence of undernourishment",y_axis_units:"% of population",indicator_360:"WB_WDI_SN_ITK_DEFC_ZS",keyFact:"115 million ",keyFactLabel:"more people faced hunger in 2024, compared to 2015.",scenes:[{_key:"k2232",type:"scene",id:"global15",text:"Between 2001 and 2014, global hunger fell impressively, nearly halving from 13 to 7.4 percent."},{_key:"k2235",type:"scene",id:"global_full",text:"But progress has since stalled, and by 2024, the prevalence of undernourishment stood at 8.1 percent."},{_key:"k2238",type:"scene",id:"regions15",text:'This pattern is true in nearly all the world’s regions. <span style="color: rgb(4,1,16); background-color: rgb(255,152,0)">Sub-Saharan Africa</span>, <span style="color: rgb(4,1,16); background-color: rgb(78,194,192)">South Asia</span>, <span style="color: rgb(255,255,255); background-color: rgb(243,87,142)">East Asia & Pacific</span>, and <span style="color: rgb(255,255,255); background-color: rgb(12,124,104)">Latin America & the Caribbean</span> all saw significant improvements in the early 2000s...'},{_key:"k2253",type:"scene",id:"regions_full",text:"…only for gains to then slow or reverse."},{_key:"k2256",type:"scene",id:"risen",text:'In <span style="color: rgb(255,255,255); background-color: rgb(12,124,104)">Latin America & the Caribbean</span>, and <span style="color: rgb(255,255,255); background-color: rgb(243,87,142)">East Asia & Pacific</span> progress in ending hunger largely stalled between 2015 and 2024.'},{_key:"k2271",type:"scene",id:"mea",text:'The most concerning trend is in the <span style="color: rgb(255,255,255); background-color: rgb(102,74,182)">Middle East & North Africa, Afghanistan and Pakistan</span> and <span style="color: rgb(4,1,16); background-color: rgb(255,152,0)">Sub-Saharan Africa,</span> where hunger rose continuously for more than a decade since 2012. By 2024, nearly 290 million people faced hunger in Sub-Saharan Africa. In the Middle East, North Africa, Afghanistan and Pakistan, the figure was 100 million. Together, that is more than half of the people living in hunger globally.'}]},{_key:"k2295",type:"subhed",text:"Are countries on track to end hunger?"},{_key:"k2296-538082db4712",type:"text",text:`The Sustainable Development Goals (SDGs) set an ambitious target to end hunger by 2030 (SDG 2.1). A country is considered to have achieved this target  when its prevalence of undernourishment falls to 2.5 percent or below.<div class="summary reference"><div class="bg" aria-label="reference 3"><label for='reference_3_2_681842539' aria-hidden="true">3</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_3_2_681842539'/><div class="details">FAO. <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>).</div></div>`},{_key:"k2296-ef7f21e2eee3",type:"text",text:"But with global progress reversing in recent years, the world is increasingly off track. So how are individual countries performing against this target and where is meaningful progress being made?"},{_key:"ab8be123ef41",type:"scroller",graphic:"undernourishment_progress",title:"Many countries have reversed progress, but some beat the odds",subtitle:"",source:`Mahler et al., FAO, and WDI (2026).<div class="summary reference"><div class="bg" aria-label="reference 4"><label for='reference_4_1_774941864' aria-hidden="true">4</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_4_1_774941864'/><div class="details">Data from <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>). Estimates based on methodology from Mahler, D G, Serajuddin, U, Wadhwa, D and Yonzan, N. 2026. <a href="https://documents.worldbank.org/en/publication/documents-reports/documentdetail/099455004132637249" target="_blank" rel="external">The World Is Developing at Its Slowest Pace in 75 Years</a>. Washington DC: World Bank Group. </div></div>`,visSize:"fullScreen",visdescription:"The chart compares changes in the prevalence of undernourishment, measured as a percentage of the population, across countries from 2015 to 2024. Each line shows a country’s actual change over this period, while a marker indicates the expected change based on its starting level. Countries are also grouped by their speed of progress, ranging from regression to very fast progress. Many countries experienced increases in undernourishment or made less progress than expected, while some countries reduced undernourishment faster than expected. Senegal is highlighted as an example, reaching 5.3% prevalence of undernourishment in 2024.",data:"undernourishment_progress",anchorKey:"ab8be123ef41",disableDataDownload:!1,disableScreenshot:!1,select_country:"Select countries to highlight",regression:"regression",standstill:"standstill",slow:"slow",typical:"typical",fast:"fast",very_fast:"very fast",progress_speed:"Speed of progress",x_axis_title:"Prevalence of undernourishment",x_axis_units:"% of population",expected:"Expected",indicator_360:"WB_WDI_SN_ITK_DEFC_ZS",keyFact:"In 51 economies",keyFactLabel:"hunger has worsened or made no progress since 2015.",scenes:[{_key:"c265390e3f31",type:"scene",id:"2015_values",text:"Among countries that have yet to meet SDG target 2.1, the prevalence of undernourishment in 2015 ranged from more than 60 percent in Somalia to 2.8 percent in Tunisia."},{_key:"f97f8e7ed64b",type:"scene",id:"typical_progress",text:`To put this into perspective, we use historical country-level data for 2001-24 to calculate a ‘typical’ path of progress. The gray dots show where each country could have reached by 2024 if it had followed this typical path.<div class="summary"><div class="bg" aria-label="footnote"><label class="footnote" aria-hidden="true" for='footnote_1661137160_1'>i</label></div><input type="checkbox" role="switch" aria-label="read footnote" id='footnote_1661137160_1'/><div class="details">More details on the methodology can be found on <a href="https://data360.worldbank.org/en/atlas/measuring-progress" target="_blank" rel="external">this page</a>.</div></div> Given the progress made in the early 2000s, most countries were expected to achieve moderate reductions in hunger. `},{_key:"a43e0f18baf4",type:"scene",id:"reverse",text:"However, many countries fell short of this typical path. Over the following decade, progress reversed in nearly 50 economies, including countries as diverse as Morocco, Mali, Syria, Kenya, and Haiti."},{_key:"e0462dd53224",type:"scene",id:"standstill",text:"In another 15 countries—including Indonesia, Namibia, and Tanzania— undernourishment levels remained largely unchanged, with little to no improvement over the decade."},{_key:"f62321763fa7",type:"scene",id:"fast_progress",text:"A handful of countries—including Senegal, the Philippines, Bangladesh, Togo, and Mozambique—beat the odds, making faster-than-expected progress in reducing undernourishment."},{_key:"7969480c0f3b",type:"scene",id:"typical",text:"These countries didn’t just follow the typical path; they outpaced it by three to four times. Take Senegal: if it had progressed at the typical rate for a country with 10 percent of the population undernourished, the prevalence of undernourishment would have fallen by just 1.5 percentage points by 2024. Instead, it reduced four times faster, bringing the share of population that was undernourished down to 5 percent."}]},{_key:"fc5810fb27dc-41c290ccdfc5",type:"text",text:"What drove Senegal's rapid progress against malnutrition? The answer lies in a combination of sustained economic growth, agricultural gains, and deliberate policy choices that reinforced each other over time."},{_key:"fc5810fb27dc-e796186985e7",type:"text",text:`At the foundation, stable economic growth helped reduce poverty, while cereal yields improved at a rate faster than the Sub-Saharan African average, expanding the overall food availability. These structural gains created the conditions for better nutrition outcomes.<div class="summary reference"><div class="bg" aria-label="reference 5"><label for='reference_5_1_964396958' aria-hidden="true">5</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_5_1_964396958'/><div class="details">Samanpreet Brar, Nadia Akseer, Mohamadou Sall, Kaitlin Conway, Ibrahima Diouf, Karl Everett, Muhammad Islam, Papa Ibrahima Sylmang Sène, Hana Tasic, Jannah Wigle, Zulfiqar Bhutta, <a href="https://doi.org/10.1093/ajcn/nqaa151" target="_blank" rel="external">Drivers of stunting reduction in Senegal: a country case study</a>, The American Journal of Clinical Nutrition, Volume 112, Supplement 2, 2020, Pages 860S-874S, ISSN 0002-9165,
</div></div>`},{_key:"c7140d35133d",type:"vis",graphic:"poverty_yield_senegal",title:"Faster poverty reduction and higher cereal yields supported progress in reducing hunger in Senegal",subtitle:"",source:`FAO and WDI (2026).<div class="summary reference"><div class="bg" aria-label="reference 6"><label for='reference_6_1_1028069303' aria-hidden="true">6</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_6_1_1028069303'/><div class="details"><a href="https://www.fao.org/faostat/en/#data/QCL" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/AG.YLD.CREL.KG" target="_blank" rel="external">AG.YLD.CREL.KG</a>; <a href="https://data.worldbank.org/indicator/SI.POV.DDAY" target="_blank" rel="external">SI.POV.DDAY</a>).</div></div>`,visSize:"default",visdescription:"The chart compares changes in extreme poverty and cereal yields in Senegal and Sub-Saharan Africa from 1990 to 2024. In Senegal, the share of the population living on less than $3 a day fell from 29% to 16%, compared with a decline from 62% to 45% across Sub-Saharan Africa. Over the same period, Senegal’s cereal yields increased from about 0.8 to 2.0 tons per hectare, surpassing the Sub-Saharan African average, which rose from about 1.1 to 1.5 tons per hectare. Together, the charts show Senegal’s faster poverty reduction and stronger growth in cereal yields over this period.",data:"poverty_yield_senegal",anchorKey:"c7140d35133d",disableDataDownload:!1,disableScreenshot:!1,yield_axis_title:"Cereal yield",yield_axis_units:"kg per hectare",poverty_axis_units:"% of population",poverty_axis_title:"Poverty headcount ratio, $3/day (2021 PPP)",indicator_360:"WB_WDI_SI_POV_DDAY"},{_key:"a52cd644e2d2-e796186985e7",type:"text",text:"But these gains were not enough on their own."},{_key:"a52cd644e2d2-6c068d4ae350",type:"text",text:`The government established the Cellule de Lutte contre la Malnutrition (CLM), housed in the Prime Minister's Office, as a multisectoral coordination body bringing together health, education, water, sanitation, and agriculture ministries under a single governance framework. This approach is widely credited as central to Senegal’s success in reducing <strong>child stunting</strong> – a condition in which children are too short for their age because of chronic malnutrition, which can impair physical and cognitive development and have lasting effects on health, learning, and future earning potential. It made nutrition a whole-of-government priority, recognizing that progress depends on coordinated action across multiple sectors, not just the health system.<div class="summary reference"><div class="bg" aria-label="reference 5"><label for='reference_5_2_964396958' aria-hidden="true">5</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_5_2_964396958'/><div class="details">Samanpreet Brar, Nadia Akseer, Mohamadou Sall, Kaitlin Conway, Ibrahima Diouf, Karl Everett, Muhammad Islam, Papa Ibrahima Sylmang Sène, Hana Tasic, Jannah Wigle, Zulfiqar Bhutta, <a href="https://doi.org/10.1093/ajcn/nqaa151" target="_blank" rel="external">Drivers of stunting reduction in Senegal: a country case study</a>, The American Journal of Clinical Nutrition, Volume 112, Supplement 2, 2020, Pages 860S-874S, ISSN 0002-9165,
</div></div> `},{_key:"a52cd644e2d2-b1fb2db2b326",type:"text",text:`Operating within this framework, large-scale programs delivered growth monitoring, supplementary feeding, caregiver education, malnutrition screening, and early-childhood services at community level.<div class="summary reference"><div class="bg" aria-label="reference 5"><label for='reference_5_3_964396958' aria-hidden="true">5</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_5_3_964396958'/><div class="details">Samanpreet Brar, Nadia Akseer, Mohamadou Sall, Kaitlin Conway, Ibrahima Diouf, Karl Everett, Muhammad Islam, Papa Ibrahima Sylmang Sène, Hana Tasic, Jannah Wigle, Zulfiqar Bhutta, <a href="https://doi.org/10.1093/ajcn/nqaa151" target="_blank" rel="external">Drivers of stunting reduction in Senegal: a country case study</a>, The American Journal of Clinical Nutrition, Volume 112, Supplement 2, 2020, Pages 860S-874S, ISSN 0002-9165,
</div></div>`},{_key:"a52cd644e2d2-f49d9fcaa7f4",type:"text",text:"Although Senegal's story is one of meaningful, coordinated progress, it is not yet a complete one. Dietary diversity remains insufficient in many areas, breastfeeding practices fall short of recommended standards, and access to services is still limited in the most food-insecure regions."},{_key:"6e7e3dc869a8",type:"scroller",graphic:"undernourishment_projections",title:"At today’s pace, when could countries end undernourishment?",subtitle:"",source:`Mahler et al., FAO, and WDI (2026).<div class="summary reference"><div class="bg" aria-label="reference 4"><label for='reference_4_2_774941864' aria-hidden="true">4</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_4_2_774941864'/><div class="details">Data from <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>). Estimates based on methodology from Mahler, D G, Serajuddin, U, Wadhwa, D and Yonzan, N. 2026. <a href="https://documents.worldbank.org/en/publication/documents-reports/documentdetail/099455004132637249" target="_blank" rel="external">The World Is Developing at Its Slowest Pace in 75 Years</a>. Washington DC: World Bank Group. </div></div>`,visSize:"default",visdescription:"The chart shows how the prevalence of undernourishment, measured as a percentage of the population, could change through 2049 if countries continue at different development speeds. Historical trends from 2015 to 2024 are shown for multiple countries, with Kenya and Senegal highlighted. From 2024 onward, projections compare progress at a typical development pace with the faster pace achieved by Senegal. For a country with 35% undernourishment in 2024, the prevalence would fall to about 19% by 2049 at a typical development pace, compared with about 4% at Senegal’s pace. The visualization illustrates how faster development could substantially accelerate progress toward ending undernourishment. In the final interactive step, visitors can search for a country to explore its historical trend and projected path.",data:"undernourishment_projections",anchorKey:"6e7e3dc869a8",disableDataDownload:!1,disableScreenshot:!1,y_axis_title:"Prevalence of undernourishment",y_axis_units:"% of population",senegal_pace:"With Senegal's development pace",typical_pace:"With typical development pace",indicator_360:"WB_WDI_SN_ITK_DEFC_ZS",scenes:[{_key:"a8c22b16edb7",type:"scene",id:"senegal",text:"If Senegal sustains its current pace of progress, which is four times faster than expected, it could nearly eliminate undernourishment by 2038—just 12 years from now."},{_key:"da59a51eb85f",type:"scene",id:"kenya_typical",text:'But as we saw earlier, many countries have lost ground over the past decade. The setbacks have been so severe that even if these countries returned to the average pace of progress, they would be far from ending hunger. For example, even if Kenya returned to the <span data-color-id="cat2" class="cat2">typical path</span>, almost 1 in 5 people would still be undernourished by 2050.'},{_key:"83aabdad0960",type:"scene",id:"kenya_senegal_speed",text:`But if it could match <span data-color-id="cat1" class="cat1">Senegal's pace</span>, it could also come close to ending hunger by 2050.`},{_key:"0d49f03c0c7f",type:"scene",id:"all_countries",text:`Are you curious about how your country compares? Use the dropdown search bar to see where it is headed at a <span data-color-id="cat2" class="cat2">typical pace</span>, and how much faster it could get there by matching <span data-color-id="cat1" class="cat1">Senegal's progress</span>.`}]},{_key:"k2218-282e7e0e5a32",type:"text",text:`Measuring hunger is challenging, and the prevalence of undernourishment captures only part of the picture. This measure does not rely on household survey data, a common source of development statistics. Instead, it draws on national accounts, combining national-level information on food production and availability, income levels, and population to produce a rough estimate of inadequate calorie intake.<div class="summary reference"><div class="bg" aria-label="reference 3"><label for='reference_3_3_681842539' aria-hidden="true">3</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_3_3_681842539'/><div class="details">FAO. <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>).</div></div>`},{_key:"k2225-k2227",type:"text",text:`This approach has clear limitations as it cannot capture individual or household experiences of food insecurity. Yet, it remains broadly comparable across countries and time, and as a result, provides the most consistent long-term global measure of hunger.<div class="summary reference"><div class="bg" aria-label="reference 2"><label for='reference_2_2_1454908558' aria-hidden="true">2</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_2_2_1454908558'/><div class="details">FAO. “I<a href="http://www.fao.org/sustainable-development-goals-data-portal/data/indicators/2.1.1-prevalence-of-undernourishment/en" target="_blank" rel="external">ndicator 2.1.1 - Prevalence of undernourishment.</a>” SDG Indicators Data Portal. Food and Agriculture Organization of the United Nations. </div></div>`},{_key:"1202cb37e643",type:"subhed",text:"Where are the world's hunger hotspots?"},{_key:"k2353-b94fbbc284b8",type:"text",text:`To complement this long-term view, measuring hunger hotspots captures severe and often sudden crises. The Hunger Hotspots Report—a collaborative early-warning product launched in 2020 and updated every three to four months— identifies where conditions are most likely to deteriorate. The report flags countries and economies at highest risk of acute food insecurity in the near term and highlights the key drivers pushing people toward hunger.<div class="summary reference"><div class="bg" aria-label="reference 7"><label for='reference_7_1_1186905595' aria-hidden="true">7</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_7_1_1186905595'/><div class="details">WFP and FAO. 2026. <a href="https://openknowledge.fao.org/items/e5a28756-7050-4ef2-9545-6759d506b5f7" target="_blank" rel="external">Hunger Hotspots. FAO–WFP Early Warnings on Acute Food Insecurity: June to November 2026 Outlook.</a> Rome: World Food Program and the Food and Agriculture Organization of the United Nations.</div></div>`},{_key:"k2353-d3b7fa41cbeb",type:"text",text:"It identifies hunger hotspots by combining current and projected acute food insecurity data with analysis of likely future shocks—including conflict, economic instability, and extreme weather—as well as underlying vulnerabilities and humanitarian access constraints. It then complements these data with expert assessments, ultimately identifying those requiring urgent action."},{_key:"k2353-3cececb2e843",type:"text",text:"Looking at today's hunger hotspots and their underlying drivers helps explain the state of hunger and why it is rising."},{_key:"b524c2f3fa2a",type:"scroller",graphic:"food_insecurity_hotspots",title:"Food insecurity hotspots: 28 countries face the highest risk",subtitle:"",source:`FAO and WFP (2026).<div class="summary reference"><div class="bg" aria-label="reference 7"><label for='reference_7_2_1186905595' aria-hidden="true">7</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_7_2_1186905595'/><div class="details">WFP and FAO. 2026. <a href="https://openknowledge.fao.org/items/e5a28756-7050-4ef2-9545-6759d506b5f7" target="_blank" rel="external">Hunger Hotspots. FAO–WFP Early Warnings on Acute Food Insecurity: June to November 2026 Outlook.</a> Rome: World Food Program and the Food and Agriculture Organization of the United Nations.</div></div>`,visSize:"fullScreen",visdescription:"The map shows countries identified as food insecurity hotspots, grouped by level of concern, from countries that have been of concern in the past five years to those currently facing the highest concern. The 28 countries at highest risk are concentrated primarily in Sub-Saharan Africa, with additional hotspots in the Middle East, South and Southeast Asia, and Haiti. Countries facing the highest concern include Sudan, South Sudan, Somalia, Yemen, and Nigeria. Symbols indicate the drivers of food insecurity in selected countries, including conflict-related insecurity, displacement and social instability; climate-related dry conditions, flooding and tropical cyclones; and economic shocks.",data:"hunger_hotspots",anchorKey:"b524c2f3fa2a",disableDataDownload:!1,disableScreenshot:!1,high_concern:"High concern",very_high_concern:"Very high concern",highest_concern:"Highest concern",previous_concern:"Of concern in the last 5 years",legend_title:"Food insecurity drivers",no_concern:"No concern",conflict:"Conflict-related drivers",conflict_security:"Insecurity",displacement:"Displacement",social_instability:"Social instability",climate:"Climate-related drivers",dry_conditions:"Dry conditions",flood:"Flooding",tropical_cyclone:"Tropical cyclone",economic_shock:"Economic shock",scenes:[{_key:"fa641425a8bb",type:"scene",id:"hotspots5years",text:"In the last five years, 28 countries and economies have been classified as food insecurity hotspots, mostly in Sub-Saharan Africa and the Middle East."},{_key:"b33da2a3d2a6",type:"scene",id:"hotspots_current",text:'The most recent report (June–November 2026) identifies 13 countries and economies as hunger hotspots, with <span style="color: #ffffff; background-color: #920000">highest concerns</span> in Nigeria, Sudan, South Sudan, Yemen and Somalia.'},{_key:"f975e5c60f71",type:"scene",id:"drivers",text:"Of these 13 countries and economies, all except Madagascar are expected to face economic shocks and conflict, and 10 are expected to face climate-related concerns, such as dry conditions, flooding, or cyclones."}]},{_key:"916aba59fa19",type:"subhed",text:"What is driving the rise in hunger?"},{_key:"9c4afdd1824f-k2413",type:"text",text:`The primary drivers of food insecurity in these countries and economies are often linked to <span style="color: #FFFFFF; background-color: #C1261A">conflict</span> (for example, insecurity, displacement, or social instability) and <span style="color: #FFFFFF; background-color: #BE792B">climate</span> (for example, droughts, flooding, or tropical cyclones). The <span style="color: #FFFFFF; background-color: #A37ACD">economic impacts of the COVID-19 pandemic</span> also left many countries and economies struggling to recover from significant job losses.<div class="summary reference"><div class="bg" aria-label="reference 8"><label for='reference_8_1_1124868022' aria-hidden="true">8</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_8_1_1124868022'/><div class="details">World Bank. 2022. <a href="https://www.worldbank.org/en/publication/wdr2022" target="_blank" rel="external">World Development Report 2022: Finance for an Equitable Recovery</a>. </div></div> Rising global food prices have hit hardest in areas that rely on imports due to their lack of local food production.<div class="summary reference"><div class="bg" aria-label="reference 9"><label for='reference_9_1_1226651240' aria-hidden="true">9</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_9_1_1226651240'/><div class="details">UNCTAD. No date. <a href="https://unctad.org/system/files/official-document/ditc-tad-trade-against-hunger_en.pdf" target="_blank" rel="external">Trade Against Hunger: Exploring Trade Actions to Fight Acute Food Insecurity and the Threat of Famine</a>. United Nations Trade and Development. </div></div>`},{_key:"c18",type:"vis",graphic:"food_insecurity_matrix",title:"Food insecurity hotspots are emerging due to conflict, climate shocks, and economic shocks",subtitle:"Food insecurity hotspot drivers by country or economy",source:`FAO and WFP (2026).<div class="summary reference"><div class="bg" aria-label="reference 7"><label for='reference_7_3_1186905595' aria-hidden="true">7</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_7_3_1186905595'/><div class="details">WFP and FAO. 2026. <a href="https://openknowledge.fao.org/items/e5a28756-7050-4ef2-9545-6759d506b5f7" target="_blank" rel="external">Hunger Hotspots. FAO–WFP Early Warnings on Acute Food Insecurity: June to November 2026 Outlook.</a> Rome: World Food Program and the Food and Agriculture Organization of the United Nations.</div></div>`,visSize:"default",visdescription:"The chart shows the main drivers of food insecurity across 13 hotspot countries and economies in the latest report. Food insecurity is linked to conflict-related drivers, including insecurity, displacement, and social instability; climate-related drivers, including dry conditions, flooding, and tropical cyclones; and economic shocks. Insecurity and displacement affect most of the hotspots shown, while economic shocks are also widespread. Several countries face multiple overlapping pressures. Nigeria, South Sudan, and Yemen face both conflict- and climate-related drivers as well as economic shocks, illustrating how multiple shocks can combine to increase food insecurity.",data:"hunger_hotspots",anchorKey:"c18",disableDataDownload:!1,disableScreenshot:!1,conflict:"Conflict-related drivers",conflict_security:"Insecurity",displacement:"Displacement",social_instability:"Social instability",climate:"Climate-related drivers",dry_conditions:"Dry conditions",flood:"Flooding",tropical_cyclone:"Tropical cyclone",economic_shock:"Economic shock"},{_key:"k2423-k2425",type:"text",text:"First, let’s examine how conflict drives hunger."},{_key:"k2426",type:"subhed2",_type:"subhed2",text:"Conflict"},{_key:"k2427-k2432",type:"text",text:`Armed conflict is one of the leading drivers of hunger worldwide, with impacts that extend far beyond the battlefield. The prevalence of undernourishment has been consistently higher in fragile and conflict-affected economies than in more stable economies.<div class="summary reference"><div class="bg" aria-label="reference 3"><label for='reference_3_4_681842539' aria-hidden="true">3</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_3_4_681842539'/><div class="details">FAO. <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>).</div></div> `},{_key:"k2433-k2439",type:"text_emphasis",text:"In fragile and conflict-affected economies, about <strong>1 in 5 people </strong>face hunger."},{_key:"c23",type:"vis",graphic:"undernourishment_conflict",title:"Hunger is rising rapidly in fragile and conflict-affected economies",subtitle:"",source:`FAO and WDI (2026).<div class="summary reference"><div class="bg" aria-label="reference 3"><label for='reference_3_5_681842539' aria-hidden="true">3</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_3_5_681842539'/><div class="details">FAO. <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>).</div></div>`,visSize:"default",visdescription:"The chart shows changes in the prevalence of undernourishment, measured as a percentage of the population, from 2001 to 2024 in fragile and conflict-affected economies, other economies, and the world overall. Undernourishment in fragile and conflict-affected economies declined from about 22% in 2001 to around 15% in the mid-2010s, before reversing course and rising sharply to 21% in 2024. In comparison, the global rate was 8.1% in 2024 and the rate in other economies was 6.1%. The chart highlights a widening gap in undernourishment between fragile and conflict-affected economies and the rest of the world.",data:"undernourishment_conflict",anchorKey:"c23",disableDataDownload:!1,disableScreenshot:!1,y_axis_title:"Prevalence of undernourishment",y_axis_units:"% of population",fcs:"Fragile and conflict-affected economies",non_fcs:"Other economies",textParagraph:`In the first decade of the 21st century, undernourishment in fragile and conflict-affected economies fell from 24 percent to 16 percent, mirroring global trends. But it has since risen faster than the global average, and by 2024, about 21 percent of the people in these economies faced hunger—thats more than double the global average.<div class="summary reference"><div class="bg" aria-label="reference 3"><label for='reference_3_6_681842539' aria-hidden="true">3</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_3_6_681842539'/><div class="details">FAO. <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>).</div></div><div class="summary"><div class="bg" aria-label="footnote"><label class="footnote" aria-hidden="true" for='footnote_467943771_1'>i</label></div><input type="checkbox" role="switch" aria-label="read footnote" id='footnote_467943771_1'/><div class="details">The estimate on prevalence of undernourishment in fragile and conflict affected economies is based on the <a href="https://thedocs.worldbank.org/en/doc/d2e218e68a25ba7a31147a7455f35cae-0090082026/original/A1-FY27-FCV-List.pdf" target="_blank" rel="external">current World Bank Fragility, Conflict, and Violence Country Classifications List (FY2027)</a>.</div></div>`,indicator_360:"WB_WDI_SN_ITK_DEFC_ZS",keyFact:"1 in 5",keyFactLabel:"people in fragile and conflict-affected economies face hunger."},{_key:"k2456-k2461",type:"text",text:`Conflict destabilizes entire food systems, ultimately triggering widespread food insecurity that can engulf whole countries and economies and spill over into neighboring regions.<div class="summary reference wide"><div class="bg" aria-label="reference 10"><label for='reference_10_1_2044632292' aria-hidden="true">10</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_10_1_2044632292'/><div class="details">Omamo, S W. 2025.  “<a href="https://www.ifpri.org/blog/how-conflict-drives-hunger-six-channels-through-the-food-system/" target="_blank" rel="external">How Conflict Drives Hunger: Six Channels Through the Food System.</a>” IFPRI blog, January 24. </div></div> `},{_key:"k2462-k2464",type:"text",text:`Food systems are vulnerable to disruption at every stage, including food production,<div class="summary"><div class="bg" aria-label="footnote"><label class="footnote" aria-hidden="true" for='footnote_1832476917_1'>i</label></div><input type="checkbox" role="switch" aria-label="read footnote" id='footnote_1832476917_1'/><div class="details">Conflict often destroys farmland, livestock, and irrigation systems, while displacement forces families to abandon their crops and livelihoods.</div></div> food supply,<div class="summary"><div class="bg" aria-label="footnote"><label class="footnote" aria-hidden="true" for='footnote_976855768_1'>i</label></div><input type="checkbox" role="switch" aria-label="read footnote" id='footnote_976855768_1'/><div class="details">Local markets and supply chains break down as roads are blocked, and food becomes hard to find. With low availability in the markets, food prices rise sharply, making even the basics unaffordable and forcing many people to rely on humanitarian assistance. </div></div> economic shocks,<div class="summary"><div class="bg" aria-label="footnote"><label class="footnote" aria-hidden="true" for='footnote_509698453_1'>i</label></div><input type="checkbox" role="switch" aria-label="read footnote" id='footnote_509698453_1'/><div class="details">Food insecurity can worsen even without food supply disruptions. Economic instability—driven by contracting economies, high inflation, or currency devaluation—can push food prices upward, making it harder for households to afford food.</div></div> and aid delivery.<div class="summary reference wide"><div class="bg" aria-label="reference 10"><label for='reference_10_2_2044632292' aria-hidden="true">10</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_10_2_2044632292'/><div class="details">Omamo, S W. 2025.  “<a href="https://www.ifpri.org/blog/how-conflict-drives-hunger-six-channels-through-the-food-system/" target="_blank" rel="external">How Conflict Drives Hunger: Six Channels Through the Food System.</a>” IFPRI blog, January 24. </div></div>`},{_key:"k2493-k2495",type:"text",text:"Such disruptions lead to rising food prices, and while price spikes often begin in areas that are directly affected by violence, their effects tend to ripple across entire economies because food supply chains are deeply interconnected. Myanmar offers a stark example. "},{_key:"c31",type:"scroller",graphic:"myanmar_foodprices_conflict",title:"Internal conflict triggered nationwide food price spikes in Myanmar",subtitle:"Circles on the map represent violent events with fatalities. The size of the circle represents the number of fatalities.",source:`Andrée, B. P. J. (2021).<div class="summary reference wide"><div class="bg" aria-label="reference 11"><label for='reference_11_1_2023260570' aria-hidden="true">11</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_11_1_2023260570'/><div class="details">Andrée, B. P. J. (2021). <a href="https://microdata.worldbank.org/index.php/catalog/4509" target="_blank" rel="external">Monthly food price inflation estimates by country</a> (Version 2026-11-02). WLD_2021_RTFP-CTRY_v02_M. Washington, DC: World Bank Microdata Library.</div></div>`,visSize:"default",visdescription:"The visualization shows the relationship between violent conflict and rising food prices in Myanmar from 2021 to November 2025. A map shows the locations of violent events with fatalities, with larger circles representing more fatalities. The accompanying charts show that monthly violent events rose sharply and frequently exceeded 100 events during 2022 and 2023, before declining to 46 in November 2025. Over the same period, the food price index rose from around 1 in 2021, peaked above 6 in 2024, and remained elevated at 5.21 in November 2025. Overall, the visualization shows that food prices increased substantially during a period of widespread violent conflict across Myanmar.",data:"myanmar_prices_conflicts",anchorKey:"c31",disableDataDownload:!1,disableScreenshot:!1,events_title:"Number of monthly violent events with fatalities",price_title:"Food price index",publish_progress:"true",gallery_thumbnail:"global-hunger_myanmar_map_charts",scenes:[{_key:"k2496",type:"scene",id:"intro",text:"Following a surge in conflict incidents beginning in February 2021, food prices rose sharply and have stayed high even as violence has eased. According to the World Food Programme, prices have more than quadrupled since the conflict began, deepening food insecurity for millions."}]},{_key:"k2506-k2510",type:"text",text:'Are you curious about how food prices have changed over time for other countries? Explore the <a href="https://microdata.worldbank.org/index.php/catalog/4509" target="_blank" rel="external">World Bank Group’s dashboard</a> to track monthly food price inflation estimates by country.'},{_key:"k2506-d1f327cd6b8d",type:"text",text:`Some conflicts have impacts that reach beyond national and regional borders. Russia’s invasion of Ukraine, for instance, disrupted global agricultural exports, including wheat, maize, fertilizer, and other staples. With both countries among the world’s major grain exporters, the sudden interruption in supply chains sent global food prices soaring, hitting low-income and import-dependent countries hardest. The crisis underscored the vulnerability of global food systems to large-scale conflicts, as prices remained volatile and supplies constrained until alternative trade routes and new supply channels were gradually established.<div class="summary reference wide"><div class="bg" aria-label="reference 12"><label for='reference_12_1_1179443950' aria-hidden="true">12</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_12_1_1179443950'/><div class="details">European Council. “<a href="https://www.consilium.europa.eu/en/infographics/how-the-russian-invasion-of-ukraine-has-further-aggravated-the-global-food-crisis/" target="_blank" rel="external">How the Russian Invasion of Ukraine Has Further Aggravated the Global Food Crisis</a>.” Archived content. </div></div>`},{_key:"k2511-k2513",type:"text",text:"Conflict frequently also traps communities in a cycle of poverty and food insecurity, as families lose their livelihoods and assets, leaving them unable to recover after the fighting stops. As a result, addressing hunger in conflict-affected regions is a humanitarian priority."},{_key:"k2514-k2516",type:"text",text:"Next, let’s look at how climate impacts hunger."},{_key:"k2517",type:"subhed2",_type:"subhed2",text:"Climate"},{_key:"k2518-k2522",type:"text",text:`Food security depends on productive agriculture that can keep up with the growing demand of a rising global population. And farming depends on stable climate conditions, and is highly sensitive to shifts in temperature, rainfall, and other weather patterns.<div class="summary reference wide"><div class="bg" aria-label="reference 13"><label for='reference_13_1_514605425' aria-hidden="true">13</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_13_1_514605425'/><div class="details">FAO, IFAD, UNICEF, WFP and WHO. 2018. <a href="https://www.fao.org/docs/devhlpelibraries/default-document-library/hlpe-fsn-issues-papers_conflicts-and-fsn.pdf" target="_blank" rel="external">The State of Food Security and Nutrition in the World 2018. Building climate resilience for food security and nutrition</a>. Rome, FAO.</div></div>`},{_key:"k2523-k2530",type:"text",text:`With rising global temperatures and an increase in climate-related natural hazard events, agricultural productivity growth is expected to slow down<div class="summary reference wide"><div class="bg" aria-label="reference 14"><label for='reference_14_1_1497331645' aria-hidden="true">14</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_14_1_1497331645'/><div class="details">Ortiz-Bobea, A, Ault, T R, Carrillo, C M, Chambers, R G and Lobell, D B. 2021. “<a href="https://www.nature.com/articles/s41558-021-01000-1" target="_blank" rel="external">Anthropogenic Climate Change Has Slowed Global Agricultural Productivity Growth</a>.” Nature Climate Change 11: 306–312. </div></div> with severe consequences for food security.<div class="summary reference wide"><div class="bg" aria-label="reference 15"><label for='reference_15_1_339347331' aria-hidden="true">15</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_15_1_339347331'/><div class="details">Thomas, V and Lopez, R. 2015. <a href="https://www.adb.org/sites/default/files/publication/176899/ewp-466.pdf" target="_blank" rel="external">Global Increase in Climate-Related Disasters</a>. Asian Development Bank Economics Working Paper Series No. 466. </div></div>`},{_key:"c3fc1c8ac012-9cc20a4d8337",type:"text_emphasis",text:"Climate change is  increasing the frequency and intensity of droughts, floods, storms, and extreme heat with severe consequences for food security."},{_key:"k2537-7f40df1ff6a2",type:"text",text:`This point is illustrated by the devastating floods that struck Pakistan’s Sindh province in August 2022, among the worst in the country’s history. To understand how the floods affected agriculture, we use satellite images to measure the health of the province’s vegetation before and after the disaster. Using the Normalized Difference Vegetation Index (NDVI) helps us compare how green the land was before and after the floods in order to estimate the extent of crop damage and how different areas were affected.<div class="summary reference wide"><div class="bg" aria-label="reference 16"><label for='reference_16_1_1786194114' aria-hidden="true">16</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_16_1_1786194114'/><div class="details">Qamer, F M, Abbas, S, Ahmad, B, Hussain, A, Salman, A, Muhammad, D, Nawaz, M, Shrestha, S, Iqbal, B and Thapa, S. 2023. “<a href="https://www.nature.com/articles/s41598-023-30347-y" target="_blank" rel="external">A Framework for Multi-sensor Satellite Data to Evaluate Crop Production Losses: The Case Study of 2022 Pakistan Floods.</a>” Nature Scientific Reports 13: 4240. </div></div>`},{_key:"c40",type:"scroller",graphic:"ndvi_map_scroller",title:"In 2022, extreme floods damaged more than half of Sindh’s cropland",subtitle:"",source:`Qamer et al (2023).<div class="summary reference wide"><div class="bg" aria-label="reference 16"><label for='reference_16_2_1786194114' aria-hidden="true">16</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_16_2_1786194114'/><div class="details">Qamer, F M, Abbas, S, Ahmad, B, Hussain, A, Salman, A, Muhammad, D, Nawaz, M, Shrestha, S, Iqbal, B and Thapa, S. 2023. “<a href="https://www.nature.com/articles/s41598-023-30347-y" target="_blank" rel="external">A Framework for Multi-sensor Satellite Data to Evaluate Crop Production Losses: The Case Study of 2022 Pakistan Floods.</a>” Nature Scientific Reports 13: 4240. </div></div>`,visSize:"default",visdescription:"The map shows the extent and severity of flood damage to cropland across Sindh, Pakistan, during the extreme floods of 2022. Cropland is classified on a scale from no damage to moderate and extreme damage. More than half of Sindh’s cropland experienced damage, with the map showing how the severity varied across the province. Major cities, including Karachi, Hyderabad, Larkana, and Sukkur, are marked to provide geographic reference.",data:"",anchorKey:"c40",disableDataDownload:!1,disableScreenshot:!1,no_damage:"No damage",moderate_damage:"Moderate damage",extreme_damage:"Extreme damage",ndvi:"Normalized Difference Vegetation Index (NDVI)",damage_level:"Level of damage",scenes:[{_key:"k2546",type:"scene",id:"intro",text:"This is Sindh province in southeastern Pakistan."},{_key:"k2549",type:"scene",id:"cultivated",text:`One-third of the province is <span style="color: rgb(255,255,255); background-color: rgb(100,198,134)">agricultural land</span>. The region, which is central to Pakistan's food supply, produces staple cereals (such as wheat and rice), industrial crops (such as cotton and sugarcane), fruit (such as mango and guava), and horticultural crops (such as chili, tomato, and sunflower).`},{_key:"k2555",type:"scene",id:"ndvi_before",text:'In August 2021, much of Sindh province was green. <span style="color: rgb(255,255,255); background-color: rgb(1,133,113)">Positive NDVI values </span>reflect normal vegetation conditions, while <span style="color: rgb(255,255,255); background-color: rgb(166,97,26)">negative NDVI values</span> depict areas affected by flood-induced damage and reduced greenness.'},{_key:"k2564",type:"scene",id:"ndvi_after",text:`During the 2022 floods, an analysis projected severe production losses, including 88 percent of cotton, 80 percent of rice, and 60 percent of sugarcane.<div class="summary reference wide"><div class="bg" aria-label="reference 16"><label for='reference_16_3_1786194114' aria-hidden="true">16</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_16_3_1786194114'/><div class="details">Qamer, F M, Abbas, S, Ahmad, B, Hussain, A, Salman, A, Muhammad, D, Nawaz, M, Shrestha, S, Iqbal, B and Thapa, S. 2023. “<a href="https://www.nature.com/articles/s41598-023-30347-y" target="_blank" rel="external">A Framework for Multi-sensor Satellite Data to Evaluate Crop Production Losses: The Case Study of 2022 Pakistan Floods.</a>” Nature Scientific Reports 13: 4240. </div></div>`},{_key:"k2569",type:"scene",id:"ndvi_difference",text:`T<strong>he floods affected around 33 million people;</strong> roughly 13 percent of the country’s total population.<div class="summary reference wide"><div class="bg" aria-label="reference 16"><label for='reference_16_4_1786194114' aria-hidden="true">16</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_16_4_1786194114'/><div class="details">Qamer, F M, Abbas, S, Ahmad, B, Hussain, A, Salman, A, Muhammad, D, Nawaz, M, Shrestha, S, Iqbal, B and Thapa, S. 2023. “<a href="https://www.nature.com/articles/s41598-023-30347-y" target="_blank" rel="external">A Framework for Multi-sensor Satellite Data to Evaluate Crop Production Losses: The Case Study of 2022 Pakistan Floods.</a>” Nature Scientific Reports 13: 4240. </div></div> It also affected more than half of the province’s cropland.`}]},{_key:"k2591-k2595",type:"text",text:`In such natural hazard events, disruptions are not confined to the destruction of agricultural land. Storage and food processing infrastructure can also get damaged and transport routes blocked, affecting the entire food supply chain. For communities already facing poverty or marginalization, such shocks translate into immediate food insecurity, as households lose both subsistence harvests and market access.<div class="summary reference wide"><div class="bg" aria-label="reference 17"><label for='reference_17_1_1848989018' aria-hidden="true">17</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_17_1_1848989018'/><div class="details">WFP USA. 2024. “<a href="https://wfpusa.org/news/how-climate-change-is-causing-world-hunger/?form=GT-3xMatch_Gen_WEB_UNR" target="_blank" rel="external">How Climate Change is Causing World Hunger</a>.” World Food Program USA, April 29 (updated February 3, 2026). </div></div>`},{_key:"k2591-084ba1bdecec",type:"text",text:`This risk is especially pressing today. Forecasts point to a strong El Niño, a natural climate pattern that warms ocean waters in the Pacific and can disrupt weather patterns around the world.<div class="summary reference wide"><div class="bg" aria-label="reference 18"><label for='reference_18_1_13813481' aria-hidden="true">18</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_18_1_13813481'/><div class="details">World Bank Group. (n.d.). <a href="https://climateknowledgeportal.worldbank.org/country/united-states/enso" target="_blank" rel="external">El Niño–Southern Oscillation</a> (ENSO): United States. Climate Change Knowledge Portal. </div></div> It can bring drought to some agricultural regions and heavy rainfall and flooding to others, threatening harvests and livelihoods. Without early action to protect crops and food supply chains, these weather shocks could drive a significant increase in hunger.<div class="summary reference wide"><div class="bg" aria-label="reference 19"><label for='reference_19_1_1665910516' aria-hidden="true">19</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_19_1_1665910516'/><div class="details">World Bank. (2026). <a href="https://www.worldbank.org/en/brief/2023/06/09/food-security-update" target="_blank" rel="external">Food security update – October 2026</a>. </div></div>`},{_key:"k2591-k2530",type:"text",text:`The impact of climate-related events on food productivity and availability will likely be uneven across countries and increase instability in the global food supply chain. As a result of food supply chain disruptions, the food insecurity divide between low- and high-income countries may deepen further.<div class="summary reference wide"><div class="bg" aria-label="reference 20"><label for='reference_20_1_368019498' aria-hidden="true">20</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_20_1_368019498'/><div class="details">Jägermeyr, J, Müller, C, Ruane, A C, Elliott, J, Balkovic, J,  Castillo, O, Faye, B, Foster, I, Folberth, C, Franke, J A et al. 2021. “<a href="https://www.nature.com/articles/s43016-021-00400-y" target="_blank" rel="external">Climate Impacts on Global Agriculture Emerge Earlier in New Generation of Climate and Crop Models</a>.” Nature 2: 873–885. </div></div>`},{_key:"k2596-k2598",type:"text",text:"Finally, let’s look at the effects that fragility in food supply chains have on hunger."},{_key:"k2599",type:"subhed2",_type:"subhed2",text:"Fragile food supply chains"},{_key:"k2600-k2602",type:"text",text:`In many countries—particularly in Sub-Saharan Africa—hunger has worsened due to conflict and climate shocks. But these pressures are only part of the problem; there is often another reason for continuing hunger: fragile food supply chains. When supply chains are weak, they become the system’s breaking point, and are easily disrupted by violence, extreme weather, or other shocks, amplifying, rather than absorbing, the effects of a crisis.<div class="summary reference wide"><div class="bg" aria-label="reference 21"><label for='reference_21_1_1836067598' aria-hidden="true">21</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_21_1_1836067598'/><div class="details">Kunaka, Charles; Abate, Megersa Abera; Lonla, Théophile Bougna; Molla, Kisanet Haile. 2025. <a href="http://hdl.handle.net/10986/43194" target="_blank" rel="external">Transport Connectivity for Food Security in Africa: Strengthening Supply Chains.</a> World Bank. </div></div>`},{_key:"k2603-k2605",type:"text",text:"Fragility in food supply chains often stems from gaps in transport infrastructure, storage capacity, and access to markets. In much of Sub-Saharan Africa, food production is enough in aggregate, but poor transport networks prevent food from reaching deficit areas."},{_key:"4687266b5447-k2605",type:"text_emphasis",text:"Nearly one-third of African countries can produce enough food, but they struggle to supply remote regions."},{_key:"9d4df65d7075-k2605",type:"text",text:`Food often has to travel extremely long distances, raising the risk of spoilage and waste, or it has to pass through a single critical route, leaving entire regions vulnerable to disruption when these fail.<div class="summary reference wide"><div class="bg" aria-label="reference 21"><label for='reference_21_2_1836067598' aria-hidden="true">21</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_21_2_1836067598'/><div class="details">Kunaka, Charles; Abate, Megersa Abera; Lonla, Théophile Bougna; Molla, Kisanet Haile. 2025. <a href="http://hdl.handle.net/10986/43194" target="_blank" rel="external">Transport Connectivity for Food Security in Africa: Strengthening Supply Chains.</a> World Bank. </div></div>`},{_key:"k2606-k2608",type:"text",text:`These challenges are clearly reflected in hunger outcomes across Sub-Saharan Africa. Despite some early progress this century, the prevalence of undernourishment remains alarmingly high. Persistently elevated food prices point to deep structural weaknesses.<div class="summary reference wide"><div class="bg" aria-label="reference 21"><label for='reference_21_3_1836067598' aria-hidden="true">21</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_21_3_1836067598'/><div class="details">Kunaka, Charles; Abate, Megersa Abera; Lonla, Théophile Bougna; Molla, Kisanet Haile. 2025. <a href="http://hdl.handle.net/10986/43194" target="_blank" rel="external">Transport Connectivity for Food Security in Africa: Strengthening Supply Chains.</a> World Bank. </div></div>`},{_key:"k2606-c1a1a10daf8c",type:"text",text:"In fact, costs associated with food supply chains can account for nearly half the retail price of staple foods such as rice, grains, and cassava. "},{_key:"k2609-k2621",type:"text_emphasis",text:`More than one-third of locally produced food in Sub-Saharan Africa is lost or wasted as a result of fragile food supply chains, due to inadequate storage and transport infrastructure.<div class="summary reference wide"><div class="bg" aria-label="reference 21"><label for='reference_21_4_1836067598' aria-hidden="true">21</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_21_4_1836067598'/><div class="details">Kunaka, Charles; Abate, Megersa Abera; Lonla, Théophile Bougna; Molla, Kisanet Haile. 2025. <a href="http://hdl.handle.net/10986/43194" target="_blank" rel="external">Transport Connectivity for Food Security in Africa: Strengthening Supply Chains.</a> World Bank. </div></div>`},{_key:"k2622-k2624",type:"text",text:`With the highest rates of undernourishment, many Sub-Saharan African countries hold the greatest potential for rapid gains. Strengthening food supply chains—by investing in transport, storage, and market access—would reduce losses, stabilize prices, and play a crucial role in improving nutrition and broader health outcomes.<div class="summary reference wide"><div class="bg" aria-label="reference 21"><label for='reference_21_5_1836067598' aria-hidden="true">21</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_21_5_1836067598'/><div class="details">Kunaka, Charles; Abate, Megersa Abera; Lonla, Théophile Bougna; Molla, Kisanet Haile. 2025. <a href="http://hdl.handle.net/10986/43194" target="_blank" rel="external">Transport Connectivity for Food Security in Africa: Strengthening Supply Chains.</a> World Bank. </div></div>`},{_key:"ace764889c7e",type:"subhed",text:"A path forward"},{_key:"k2626-58ea6633f334",type:"text",text:"After decades of progress, global hunger has been rising, driven by conflicts that disrupt livelihoods and markets, climate shocks that damage crops and infrastructure, and fragile supply chains that deepen losses and raise food prices. These pressures reinforce each other, leaving vulnerable communities increasingly exposed to food insecurity."},{_key:"k2626-81190a736b46",type:"text",text:"Yet, this reversal of progress is not inevitable. Countries such as Senegal have beaten the odds, showing that sustained economic growth, stronger agricultural productivity, and coordinated nutrition policies can accelerate progress, even in difficult circumstances."},{_key:"k2626-6722d81ca690",type:"text",text:`But turning such gains into broader progress will require urgent, coordinated action to: prevent and respond to food crises; invest in climate-resilient agriculture and reliable transport and storage; strengthen social protection; and improve household-level data so resources reach those who are most at risk.<div class="summary reference wide"><div class="bg" aria-label="reference 22"><label for='reference_22_1_1634252623' aria-hidden="true">22</label></div><input type="checkbox" role="switch" aria-label="read reference" id='reference_22_1_1634252623'/><div class="details">Maxwell, D, Vaitla, B and Coates, J. 2014.  “<a href="https://www.sciencedirect.com/science/article/pii/S0306919214000682" target="_blank" rel="external">How Do Indicators of Household Food Insecurity Measure Up? An Empirical Comparison from Ethiopia</a>.” Food Policy 47: 107–116. </div></div> With sustained commitment, countries can build food systems that withstand shocks and renew progress toward ending hunger.`}],t=[{text:'FAO. <a href="https://www.fao.org/right-to-food/en" target="_blank" rel="external">Right to Food</a>. Food and Agriculture Organization of the United Nations.',index:0},{text:'FAO. “I<a href="http://www.fao.org/sustainable-development-goals-data-portal/data/indicators/2.1.1-prevalence-of-undernourishment/en" target="_blank" rel="external">ndicator 2.1.1 - Prevalence of undernourishment.</a>” SDG Indicators Data Portal. Food and Agriculture Organization of the United Nations. ',index:1},{text:'FAO. <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>).',index:2},{text:'Data from <a href="https://www.fao.org/faostat/en/#home" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/SN.ITK.DEFC.ZS" target="_blank" rel="external">SN.ITK.DEFC.ZS</a>). Estimates based on methodology from Mahler, D G, Serajuddin, U, Wadhwa, D and Yonzan, N. 2026. <a href="https://documents.worldbank.org/en/publication/documents-reports/documentdetail/099455004132637249" target="_blank" rel="external">The World Is Developing at Its Slowest Pace in 75 Years</a>. Washington DC: World Bank Group. ',index:3},{text:`Samanpreet Brar, Nadia Akseer, Mohamadou Sall, Kaitlin Conway, Ibrahima Diouf, Karl Everett, Muhammad Islam, Papa Ibrahima Sylmang Sène, Hana Tasic, Jannah Wigle, Zulfiqar Bhutta, <a href="https://doi.org/10.1093/ajcn/nqaa151" target="_blank" rel="external">Drivers of stunting reduction in Senegal: a country case study</a>, The American Journal of Clinical Nutrition, Volume 112, Supplement 2, 2020, Pages 860S-874S, ISSN 0002-9165,
`,index:4},{text:'<a href="https://www.fao.org/faostat/en/#data/QCL" target="_blank" rel="external">Food and Agriculture Organization</a> of the United Nations (FAO), Retrieved from World Development Indicators (<a href="https://data.worldbank.org/indicator/AG.YLD.CREL.KG" target="_blank" rel="external">AG.YLD.CREL.KG</a>; <a href="https://data.worldbank.org/indicator/SI.POV.DDAY" target="_blank" rel="external">SI.POV.DDAY</a>).',index:5},{text:'WFP and FAO. 2026. <a href="https://openknowledge.fao.org/items/e5a28756-7050-4ef2-9545-6759d506b5f7" target="_blank" rel="external">Hunger Hotspots. FAO–WFP Early Warnings on Acute Food Insecurity: June to November 2026 Outlook.</a> Rome: World Food Program and the Food and Agriculture Organization of the United Nations.',index:6},{text:'World Bank. 2022. <a href="https://www.worldbank.org/en/publication/wdr2022" target="_blank" rel="external">World Development Report 2022: Finance for an Equitable Recovery</a>. ',index:7},{text:'UNCTAD. No date. <a href="https://unctad.org/system/files/official-document/ditc-tad-trade-against-hunger_en.pdf" target="_blank" rel="external">Trade Against Hunger: Exploring Trade Actions to Fight Acute Food Insecurity and the Threat of Famine</a>. United Nations Trade and Development. ',index:8},{text:'Omamo, S W. 2025.  “<a href="https://www.ifpri.org/blog/how-conflict-drives-hunger-six-channels-through-the-food-system/" target="_blank" rel="external">How Conflict Drives Hunger: Six Channels Through the Food System.</a>” IFPRI blog, January 24. ',index:9},{text:'Andrée, B. P. J. (2021). <a href="https://microdata.worldbank.org/index.php/catalog/4509" target="_blank" rel="external">Monthly food price inflation estimates by country</a> (Version 2026-11-02). WLD_2021_RTFP-CTRY_v02_M. Washington, DC: World Bank Microdata Library.',index:10},{text:'European Council. “<a href="https://www.consilium.europa.eu/en/infographics/how-the-russian-invasion-of-ukraine-has-further-aggravated-the-global-food-crisis/" target="_blank" rel="external">How the Russian Invasion of Ukraine Has Further Aggravated the Global Food Crisis</a>.” Archived content. ',index:11},{text:'FAO, IFAD, UNICEF, WFP and WHO. 2018. <a href="https://www.fao.org/docs/devhlpelibraries/default-document-library/hlpe-fsn-issues-papers_conflicts-and-fsn.pdf" target="_blank" rel="external">The State of Food Security and Nutrition in the World 2018. Building climate resilience for food security and nutrition</a>. Rome, FAO.',index:12},{text:'Ortiz-Bobea, A, Ault, T R, Carrillo, C M, Chambers, R G and Lobell, D B. 2021. “<a href="https://www.nature.com/articles/s41558-021-01000-1" target="_blank" rel="external">Anthropogenic Climate Change Has Slowed Global Agricultural Productivity Growth</a>.” Nature Climate Change 11: 306–312. ',index:13},{text:'Thomas, V and Lopez, R. 2015. <a href="https://www.adb.org/sites/default/files/publication/176899/ewp-466.pdf" target="_blank" rel="external">Global Increase in Climate-Related Disasters</a>. Asian Development Bank Economics Working Paper Series No. 466. ',index:14},{text:'Qamer, F M, Abbas, S, Ahmad, B, Hussain, A, Salman, A, Muhammad, D, Nawaz, M, Shrestha, S, Iqbal, B and Thapa, S. 2023. “<a href="https://www.nature.com/articles/s41598-023-30347-y" target="_blank" rel="external">A Framework for Multi-sensor Satellite Data to Evaluate Crop Production Losses: The Case Study of 2022 Pakistan Floods.</a>” Nature Scientific Reports 13: 4240. ',index:15},{text:'WFP USA. 2024. “<a href="https://wfpusa.org/news/how-climate-change-is-causing-world-hunger/?form=GT-3xMatch_Gen_WEB_UNR" target="_blank" rel="external">How Climate Change is Causing World Hunger</a>.” World Food Program USA, April 29 (updated February 3, 2026). ',index:16},{text:'World Bank Group. (n.d.). <a href="https://climateknowledgeportal.worldbank.org/country/united-states/enso" target="_blank" rel="external">El Niño–Southern Oscillation</a> (ENSO): United States. Climate Change Knowledge Portal. ',index:17},{text:'World Bank. (2026). <a href="https://www.worldbank.org/en/brief/2023/06/09/food-security-update" target="_blank" rel="external">Food security update – October 2026</a>. ',index:18},{text:'Jägermeyr, J, Müller, C, Ruane, A C, Elliott, J, Balkovic, J,  Castillo, O, Faye, B, Foster, I, Folberth, C, Franke, J A et al. 2021. “<a href="https://www.nature.com/articles/s43016-021-00400-y" target="_blank" rel="external">Climate Impacts on Global Agriculture Emerge Earlier in New Generation of Climate and Crop Models</a>.” Nature 2: 873–885. ',index:19},{text:'Kunaka, Charles; Abate, Megersa Abera; Lonla, Théophile Bougna; Molla, Kisanet Haile. 2025. <a href="http://hdl.handle.net/10986/43194" target="_blank" rel="external">Transport Connectivity for Food Security in Africa: Strengthening Supply Chains.</a> World Bank. ',index:20},{text:'Maxwell, D, Vaitla, B and Coates, J. 2014.  “<a href="https://www.sciencedirect.com/science/article/pii/S0306919214000682" target="_blank" rel="external">How Do Indicators of Household Food Insecurity Measure Up? An Empirical Comparison from Ethiopia</a>.” Food Policy 47: 107–116. ',index:21}],r={config:e,content:a,references:t};export{e as config,a as content,r as default,t as references};
